/* ===== V98: مزامنة مستمرة ويا السيرفر ===== */
let syncBusy=false, syncT=null, syncPendingRefresh=null, syncFails=0;
function sSetGlobal(k,v){
  if(k==='customers') customers=v; else if(k==='orders') orders=v; else if(k==='products') products=v;
  else if(k==='settings') settings=v; else if(k==='counter') counter=+v||0; else if(k==='layout') layout=v; else if(k==='mix') mix=v;
}
function sLocal(k){
  return k==='customers'?customers:k==='orders'?orders:k==='products'?products:k==='settings'?settings:k==='counter'?counter:k==='layout'?layout:mix;
}
function sDot(){
  const b=document.getElementById('syncDot'); if(!b) return;
  const off=syncMode!=='server'||syncFails>1;
  b.textContent=off?'⚠ مو مربوط بالسيرفر':'☁ البيانات على السيرفر';
  b.className='sync-dot '+(off?'bad':'good');
}
function syncRefresh(keys){
  const ae=document.activeElement;
  if(ae&&/^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName)&&!ae.closest('.c-stage')){ syncPendingRefresh=Object.assign(syncPendingRefresh||{},keys); return }
  syncPendingRefresh=null;
  const settingsOpen=document.getElementById('page-settings').classList.contains('active');
  const run=f=>{ try{ if(typeof f==='function') f() }catch(e){} };
  if(keys.products) run(renderMenu);
  if(keys.orders){ run(renderOrders); run(ordBadge) }
  if(keys.customers) run(renderCustomers);
  if(keys.products) run(renderProducts);
  if(keys.settings){
    run(()=>zoneBuild()); run(()=>znRender());
    if(!settingsOpen) run(fillSettings);
    run(fillStore); run(renderBuy); run(renderDaily); run(renderSauce); run(renderExpenses);
  }
  if(keys.counter) run(nextNumUi);
  if(keys.layout) run(drawLinks);
}
function syncTakeServer(keys,rev){
  const changed={};
  syncApplying=true;
  Object.keys(SYNC_KEYS).forEach(k=>{
    if(!keys||!(k in keys)) return;
    const pend=syncBase[k]===undefined?null:sDiff(k,sLocal(k));
    const merged=sApply(k,keys[k],pend);
    if(sJ(merged)!==sJ(sLocal(k))){ sSetGlobal(k,merged); changed[k]=1 }
    sWrite(k,merged); syncBase[k]=sBaseOf(k,keys[k]);
  });
  syncApplying=false;
  if(rev) syncRev=rev; sSaveMeta();
  if(Object.keys(changed).length) syncRefresh(changed);
}
async function syncPush(){
  if(syncBusy){ syncSoon(); return } syncBusy=true;
  try{
    const ch={}; let n=0;
    Object.keys(SYNC_KEYS).forEach(k=>{ const d=sDiff(k,sLocal(k)); if(d){ ch[k]=d; n++ } });
    if(!n){ syncBusy=false; return }
    let seed=false;
    if(syncMode==='seed'){
      if(!(orders.length||customers.length)){ syncBusy=false; return }   /* جهاز فاضي ما يبدي البيانات */
      seed=true; Object.keys(SYNC_KEYS).forEach(k=>{ ch[k]=sDiff(k,sLocal(k))||(SYNC_KEYS[k]==='arr'?{up:[],del:[]}:SYNC_KEYS[k]==='obj'?{set:{},del:[]}:{v:sLocal(k)}) });
    }
    const r=await fetch(SYNC_URL+'?a=put',{method:'POST',headers:{'X-Safi-Key':SYNC_KEY,'Content-Type':'application/json'},body:JSON.stringify({keys:ch,since:syncRev,seed})});
    const j=await r.json();
    if(j.ok){ syncMode='server'; syncFails=0; syncTakeServer(j.keys,j.rev) }
    else if(j.err==='notseeded'){ syncMode='seed' }
    else syncFails++;
  }catch(e){ syncFails++ }
  syncBusy=false; sDot();
}
async function syncPull(){
  if(syncBusy) return;
  if(syncMode!=='server'){ syncPush(); return }
  syncBusy=true;
  try{
    const r=await fetch(SYNC_URL+'?a=get&since='+syncRev+'&t='+Date.now(),{headers:{'X-Safi-Key':SYNC_KEY},cache:'no-store'});
    const j=await r.json();
    if(j.ok){ syncFails=0; if(Object.keys(j.keys).length) syncTakeServer(j.keys,j.rev); else syncRev=j.rev }
    else syncFails++;
  }catch(e){ syncFails++ }
  syncBusy=false; sDot();
  if(syncPendingRefresh){ const ae=document.activeElement; if(!(ae&&/^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName))) syncRefresh(syncPendingRefresh) }
  const pend=Object.keys(SYNC_KEYS).some(k=>sDiff(k,sLocal(k))); if(pend) syncSoon();
}
function syncSoon(){ clearTimeout(syncT); syncT=setTimeout(syncPush,700) }
/* أي حفظ بالنظام يروح للسيرفر */
(function(){
  const orig=LS.set;
  LS.set=function(k,v){ orig.call(LS,k,v); if(!syncApplying&&typeof k==='string'&&k.startsWith('safi_')&&SYNC_KEYS[k.slice(5)]) syncSoon() };
  const vb=document.getElementById('verBadge');
  if(vb){ const d=document.createElement('div'); d.id='syncDot'; d.className='sync-dot'; vb.insertAdjacentElement('afterend',d) }
  setInterval(syncPull,6000);
  document.addEventListener('visibilitychange',()=>{ if(!document.hidden) syncPull() });
  window.addEventListener('online',syncPull);
  sDot(); setTimeout(syncPush,1500);
})();

/* ===== V98: صفحة التقارير ===== */
let repRange='today';
function repBounds(){
  const d0=new Date(); d0.setHours(0,0,0,0); const day=86400000, t0=d0.getTime();
  if(repRange==='today') return [t0,t0+day];
  if(repRange==='yday') return [t0-day,t0];
  if(repRange==='week'){ const w=(d0.getDay()+1)%7; return [t0-w*day,t0+day] }   /* الأسبوع يبدي السبت */
  if(repRange==='month'){ const m=new Date(d0.getFullYear(),d0.getMonth(),1).getTime(); return [m,t0+day] }
  if(repRange==='lmonth'){ const a=new Date(d0.getFullYear(),d0.getMonth()-1,1).getTime(), b=new Date(d0.getFullYear(),d0.getMonth(),1).getTime(); return [a,b] }
  const f=document.getElementById('repFrom').value, t=document.getElementById('repTo').value;
  const a=f?new Date(f+'T00:00').getTime():t0, b=t?new Date(t+'T00:00').getTime()+day:t0+day;
  return [Math.min(a,b-1),b];
}
const repDay=ts=>{ const d=new Date(ts); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0') };
function repData(){
  const [a,b]=repBounds();
  const all=orders.filter(o=>o.ts>=a&&o.ts<b), ok=all.filter(o=>o.status!=='cancel');
  const S=k=>ok.reduce((s,o)=>s+(+o[k]||0),0);
  const days={}, items={}, types={};
  ok.forEach(o=>{
    const k=repDay(o.ts); const d=days[k]||(days[k]={n:0,sub:0,del:0,dis:0,total:0});
    d.n++; d.sub+=+o.sub||0; d.del+=+o.del||0; d.dis+=+o.dis||0; d.total+=+o.total||0;
    const t=types[o.type]||(types[o.type]={n:0,total:0}); t.n++; t.total+=+o.total||0;
    (o.items||[]).forEach(i=>{ const it=items[i.name]||(items[i.name]={q:0,v:0}); it.q+=+i.qty||0; it.v+=(+i.qty||0)*(+i.price||0) });
  });
  return {a,b,ok,cancel:all.length-ok.length,sub:S('sub'),del:S('del'),dis:S('dis'),total:S('total'),nd:ok.filter(o=>o.dis).length,days,items,types};
}
function renderReport(){
  const R=repData(), el=id=>document.getElementById(id);
  const fmtD=ts=>new Date(ts).toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'short',day:'numeric',month:'numeric'});
  el('repSpan').textContent=fmtD(R.a)+(R.b-R.a>86400000?' — '+fmtD(R.b-1):'');
  el('repCards').innerHTML=[
    ['عدد الطلبات',fmt(R.ok.length),''],
    ['قيمة الأكل',fmt(R.sub),''],
    ['أجور التوصيل',fmt(R.del),''],
    ['الخصومات'+(R.nd?' ('+R.nd+')':''),'− '+fmt(R.dis),'bad'],
    ['الصافي المستلم',fmt(R.total),'good'],
    ['متوسط الطلب',fmt(R.ok.length?Math.round(R.total/R.ok.length):0),''],
    ['طلبات ملغية',fmt(R.cancel),R.cancel?'bad':'']
  ].map(([l,v,c])=>`<div class="rc ${c}"><span>${l}</span><b>${v}</b></div>`).join('');
  const dk=Object.keys(R.days).sort().reverse();
  el('repDays').innerHTML=dk.length?`<table class="rt"><thead><tr><th>اليوم</th><th>طلبات</th><th>الأكل</th><th>توصيل</th><th>خصم</th><th>الصافي</th></tr></thead><tbody>`+
    dk.map(k=>{ const d=R.days[k]; return `<tr><td>${fmtD(new Date(k+'T12:00').getTime())}</td><td>${d.n}</td><td>${fmt(d.sub)}</td><td>${fmt(d.del)}</td><td class="neg">${d.dis?'− '+fmt(d.dis):'0'}</td><td><b>${fmt(d.total)}</b></td></tr>` }).join('')+`</tbody></table>`:'<div class="hint">ماكو طلبات بهالفترة</div>';
  const ik=Object.keys(R.items).sort((x,y)=>R.items[y].v-R.items[x].v);
  el('repItems').innerHTML=ik.length?`<table class="rt"><thead><tr><th>الصنف</th><th>الكمية</th><th>المبلغ</th></tr></thead><tbody>`+
    ik.map(k=>`<tr><td>${esc(k)}</td><td>${fmt(R.items[k].q)}</td><td>${fmt(R.items[k].v)}</td></tr>`).join('')+`</tbody></table>`:'<div class="hint">—</div>';
  el('repTypes').innerHTML=Object.keys(R.types).map(t=>`<div class="rc"><span>${TYPE_TXT[t]||t}</span><b>${fmt(R.types[t].n)} طلب · ${fmt(R.types[t].total)}</b></div>`).join('')||'<div class="hint">—</div>';
}
function repCsv(){
  const R=repData(), q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"';
  const rows=[['رقم الطلب','التاريخ','الوقت','النوع','الزبون','التلفون','المنطقة/العنوان','الأصناف','قيمة الأكل','التوصيل','الخصم','الصافي','الحالة']];
  R.ok.slice().sort((x,y)=>x.ts-y.ts).forEach(o=>{ const d=new Date(o.ts);
    rows.push([o.num,repDay(o.ts),d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),TYPE_TXT[o.type]||o.type,o.name,o.phone,o.addr,(o.items||[]).map(i=>i.qty+'× '+i.name).join(' + '),o.sub||0,o.del||0,o.dis||0,o.total||0,(STATUSES[o.status]||[''])[0]]) });
  rows.push([]); rows.push(['المجموع','','','','','','','',R.sub,R.del,R.dis,R.total,R.ok.length+' طلب']);
  const blob=new Blob(['﻿'+rows.map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='تقرير-صافي-'+repDay(R.a)+(R.b-R.a>86400000?'_'+repDay(R.b-1):'')+'.csv';
  document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove() },1000);
}
document.getElementById('repRanges').addEventListener('click',e=>{
  const b=e.target.closest('button[data-r]'); if(!b) return;
  repRange=b.dataset.r;
  document.querySelectorAll('#repRanges button').forEach(x=>x.classList.toggle('on',x===b));
  document.getElementById('repCustom').hidden=repRange!=='custom';
  renderReport();
});
['repFrom','repTo'].forEach(id=>document.getElementById(id).addEventListener('change',renderReport));
document.getElementById('repCsvBtn').addEventListener('click',repCsv);
document.querySelector('.tab[data-page="reports"]').addEventListener('click',renderReport);

/* ===== V98: البيانات على السيرفر — كل الأجهزة تشوف نفس الشي ===== */
const SYNC_KEYS={customers:'arr',orders:'arr',products:'arr',settings:'obj',counter:'max',layout:'val',mix:'val'};
const SYNC_URL='data.php', SYNC_KEY='c7f400f0c1f4d79da5b706f9442a369b';
let syncRev=+localStorage.getItem('safi_syncrev')||0, syncMode='local', syncApplying=false;
let syncBase=(()=>{ try{ return JSON.parse(localStorage.getItem('safi_syncbase')||'{}') }catch(e){ return {} } })();
const sJ=v=>JSON.stringify(v===undefined?null:v);
function sRead(k){ try{ const v=localStorage.getItem('safi_'+k); return v==null?null:JSON.parse(v) }catch(e){ return null } }
function sWrite(k,v){ try{ localStorage.setItem('safi_'+k,JSON.stringify(v)) }catch(e){} }
function sId(k,x){ if(!x||typeof x!=='object') return ''; if(x.id!=null&&x.id!=='') return String(x.id); if(k==='orders'){ x.id='o'+(x.ts||0)+'-'+(x.num||0); return x.id } return '' }
function sBaseOf(k,v){
  const t=SYNC_KEYS[k];
  if(t==='arr'){ const m={}; (Array.isArray(v)?v:[]).forEach(x=>{ const id=sId(k,x); if(id) m[id]=sJ(x) }); return m }
  if(t==='obj'){ const m={}; Object.keys(v||{}).forEach(p=>{ m[p]=sJ(v[p]) }); return m }
  return sJ(v);
}
/* الفرق بين الي بالجهاز وآخر نسخة من السيرفر */
function sDiff(k,v){
  const t=SYNC_KEYS[k], b=syncBase[k];
  if(t==='arr'){
    if(!Array.isArray(v)) return null;
    if(k==='products') v.forEach((x,i)=>{ if(x&&typeof x==='object') x._o=i });
    const bm=(b&&typeof b==='object')?b:{}, seen={}, up=[], del=[];
    v.forEach(x=>{ const id=sId(k,x); if(!id) return; seen[id]=1; if(bm[id]!==sJ(x)) up.push(x) });
    Object.keys(bm).forEach(id=>{ if(!seen[id]) del.push(id) });
    return (up.length||del.length)?{up,del}:null;
  }
  if(t==='obj'){
    if(!v||typeof v!=='object') return null;
    const bm=(b&&typeof b==='object')?b:{}, set={}, del=[]; let n=0;
    Object.keys(v).forEach(p=>{ if(bm[p]!==sJ(v[p])){ set[p]=v[p]; n++ } });
    Object.keys(bm).forEach(p=>{ if(!(p in v)){ del.push(p); n++ } });
    return n?{set,del}:null;
  }
  return sJ(v)!==b?{v}:null;
}
/* نطبق تغييرات الجهاز الي بعدها ما وصلت فوق بيانات السيرفر */
function sApply(k,sv,ch){
  const t=SYNC_KEYS[k];
  if(!ch) return sv;
  if(t==='arr'){
    const m=new Map(); (sv||[]).forEach(x=>{ m.set(sId(k,x),x) });
    (ch.up||[]).forEach(x=>{ m.set(sId(k,x),x) }); (ch.del||[]).forEach(id=>m.delete(id));
    const a=[...m.values()];
    if(k==='products') a.sort((p,q)=>(p._o||0)-(q._o||0)); else a.sort((p,q)=>((q.ts||q.created||0)-(p.ts||p.created||0)));
    return a;
  }
  if(t==='obj'){ const o=Object.assign({},sv||{},ch.set||{}); (ch.del||[]).forEach(p=>delete o[p]); return o }
  if(t==='max') return Math.max(+sv||0,+ch.v||0);
  return ch.v;
}
function sSaveMeta(){ try{ localStorage.setItem('safi_syncrev',String(syncRev)); localStorage.setItem('safi_syncbase',JSON.stringify(syncBase)) }catch(e){} }
/* أول ما تنفتح الصفحة: نجيب البيانات من السيرفر قبل لا يشتغل النظام */
(function(){
  try{
    const x=new XMLHttpRequest();
    x.open('GET',SYNC_URL+'?a=get&since=0&t='+Date.now(),false);
    x.setRequestHeader('X-Safi-Key',SYNC_KEY); x.send();
    if(x.status!==200) return;
    const j=JSON.parse(x.responseText); if(!j.ok) return;
    if(j.empty){ syncMode='seed'; return }
    Object.keys(SYNC_KEYS).forEach(k=>{
      if(!(k in j.keys)) return;
      const pend=syncBase[k]===undefined?null:sDiff(k,sRead(k));   /* جهاز جديد: السيرفر يغلب */
      sWrite(k,sApply(k,j.keys[k],pend));
      syncBase[k]=sBaseOf(k,j.keys[k]);
    });
    syncRev=j.rev; syncMode='server'; sSaveMeta();
  }catch(e){}
})();

